package com.cartalaap.notification;
import java.util.List;import org.springframework.data.domain.PageRequest;import org.springframework.security.core.Authentication;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.cartalaap.common.ForbiddenException;import com.cartalaap.common.NotFoundException;import com.cartalaap.user.CurrentUserService;import com.cartalaap.user.User;
@Service public class NotificationService{private final NotificationRepository notifications;private final CurrentUserService currentUsers;public NotificationService(NotificationRepository notifications,CurrentUserService currentUsers){this.notifications=notifications;this.currentUsers=currentUsers;}@Transactional public void create(User recipient,User actor,NotificationType type,String message,Long targetId){if(recipient==null||actor!=null&&recipient.getId().equals(actor.getId()))return;notifications.save(new Notification(recipient,actor,type,message,targetId));}@Transactional(readOnly=true)public List<NotificationResponse>list(Authentication auth){User u=currentUsers.require(auth);return notifications.findByRecipient_IdOrderByCreatedAtDesc(u.getId(),PageRequest.of(0,50)).stream().map(NotificationResponse::from).toList();}@Transactional(readOnly=true)public NotificationResponse.Count count(Authentication auth){return new NotificationResponse.Count(notifications.countByRecipient_IdAndReadAtIsNull(currentUsers.require(auth).getId()));}@Transactional public void read(Long id,Authentication auth){User u=currentUsers.require(auth);Notification n=notifications.findById(id).orElseThrow(()->new NotFoundException("Notification not found"));var own=notifications.findByRecipient_IdOrderByCreatedAtDesc(u.getId(),PageRequest.of(0,100)).stream().anyMatch(item->item.getId().equals(id));if(!own)throw new ForbiddenException("Notification does not belong to you");n.markRead();}@Transactional public void readAll(Authentication auth){User u=currentUsers.require(auth);notifications.findByRecipient_IdOrderByCreatedAtDesc(u.getId(),PageRequest.of(0,100)).forEach(Notification::markRead);}}
